  "flow": [
    {
      "slide": 1,
      "does": "Recall encoding, storage and retrieval",
      "look_at": {"kind": "none", "shows": null},
      "teaches": []
    },
    {
      "slide": 2,
      "does": "Introduce the approved objectives",
      "look_at": {"kind": "none", "shows": null},
      "teaches": []
    },
    {
      "slide": 3,
      "does": "Teach the characteristics of the three stores",
      "look_at": {"kind": "diagram", "shows": "A comparison table of coding, capacity and duration"},
      "teaches": [1]
    },
    {
      "slide": 4,
      "does": "Explain movement between the stores",
      "look_at": {"kind": "diagram", "shows": "Attention, rehearsal and retrieval in the model"},
      "teaches": [2]
    },
    {
      "slide": 5,
      "does": "Model an explanation of remembering a code",
      "look_at": {"kind": "none", "shows": null},
      "teaches": [2]
    },
    {
      "slide": 6,
      "does": "Check a near-identical code example",
      "look_at": {"kind": "none", "shows": null},
      "teaches": [1, 2]
    },
    {
      "slide": 7,
      "does": "Correct the belief that rehearsal always guarantees learning",
      "look_at": {"kind": "none", "shows": null},
      "teaches": [2]
    },
    {
      "slide": 8,
      "does": "Teach serial position evidence and its explanation",
      "look_at": {"kind": "diagram", "shows": "Immediate recall and recall after a filled delay"},
      "teaches": [3]
    },
    {
      "slide": 9,
      "does": "Check how serial position findings support separate stores",
      "look_at": {"kind": "none", "shows": null},
      "teaches": [3]
    },
    {
      "slide": 10,
      "does": "Teach KF as a challenge to a single STM store",
      "look_at": {"kind": "diagram", "shows": "Contrasting verbal and visual short-term memory performance"},
      "teaches": [3]
    },
    {
      "slide": 11,
      "does": "Construct balanced evaluations from both studies",
      "look_at": {"kind": "none", "shows": null},
      "teaches": [3]
    },
    {
      "slide": 12,
      "does": "Apply the model to an unfamiliar everyday situation",
      "look_at": {"kind": "none", "shows": null},
      "teaches": [1, 2]
    }
  ],
  "title": {
    "template": "title",
    "heading": "The multi-store model of memory",
    "lead": "Recall: what do encoding, storage and retrieval mean?",
    "picture": null
  },
  "slides": [
    {
      "template": "big-visual",
      "heading": "Three stores, different characteristics",
      "lead": "Atkinson and Shiffrin (1968): compare the stores.",
      "figure": {
        "kind": "table",
        "shows": "The typical coding, capacity and duration of the three memory stores",
        "alt": "A table compares sensory register, short-term memory and long-term memory by coding, capacity and duration.",
        "title": null,
        "header": ["Store", "Coding", "Capacity", "Duration"],
        "rows": [
          ["Sensory register", "Modality-specific", "Very large", "Very brief"],
          ["Short-term memory", "Mainly acoustic", "About 7 ± 2 items", "About 18–30 seconds"],
          ["Long-term memory", "Mainly semantic", "Potentially unlimited", "Potentially lifelong"]
        ]
      }
    },
    {
      "template": "visual-text",
      "heading": "How does information move?",
      "lead": "The stores are linked by processes.",
      "points": [
        {"label": "Attention", "text": "Selects sensory information for STM."},
        {"label": "Rehearsal", "text": "Keeps information in STM; prolonged rehearsal can transfer it to LTM."}
      ],
      "figure": {
        "kind": "flow",
        "shows": "The multi-store model, including a rehearsal loop and retrieval from LTM to STM",
        "alt": "Attention moves information from sensory register to STM. Rehearsal maintains STM and can transfer information to LTM. Retrieval returns it to STM.",
        "title": null,
        "nodes": ["Sensory register", "STM", "LTM"],
        "links": [
          {"from": 0, "to": 1, "label": "Attention"},
          {"from": 1, "to": 1, "label": "Maintenance rehearsal"},
          {"from": 1, "to": 2, "label": "Prolonged rehearsal"},
          {"from": 2, "to": 1, "label": "Retrieval"}
        ]
      }
    },
    {
      "template": "steps",
      "heading": "Worked example: a door code",
      "points": [
        "Maya hears 4826 and attends to it: sensory register → STM.",
        "She repeats 4826: maintenance rehearsal keeps it in STM.",
        "The model predicts that prolonged rehearsal can transfer it to LTM.",
        "Next day, she recalls 4826: retrieval brings it from LTM to STM."
      ],
      "figure": null
    },
    {
      "template": "practice",
      "heading": "Your turn: a locker code",
      "questions": [
        "Noah hears 7315 and focuses on it. Name the process and the two stores involved.",
        "He repeats 7315 for 20 seconds. Explain how this affects STM.",
        "Next day, he recalls 7315. Explain this transfer and name LTM’s main coding."
      ],
      "instruction": "Write a short explanation for each stage.",
      "picture": null
    },
    {
      "template": "explain",
      "heading": "Does repetition guarantee lasting memory?",
      "lead": "Repeating information can keep it available now without guaranteeing that it will be remembered later.",
      "points": [
        {"label": "Example", "text": "You repeat a code until you enter it, then soon forget it."},
        {"label": "Model claim", "text": "Prolonged rehearsal can transfer information to LTM; brief repetition need not do so."}
      ]
    },
    {
      "template": "visual-text",
      "heading": "Glanzer and Cunitz: serial position",
      "lead": "Word-list recall supports separate STM and LTM stores.",
      "points": [
        "Primacy: early words receive more rehearsal and enter LTM.",
        "Recency: final words remain available in STM.",
        "A 30-second counting delay reduced recency, but preserved primacy."
      ],
      "figure": {
        "kind": "line-graph",
        "shows": "A schematic serial position curve: immediate recall has primacy and recency; a filled delay reduces recency",
        "alt": "Both curves show better recall for early words. Immediate recall also rises for final words; recall after a filled delay does not.",
        "title": null,
        "x": {"label": "Position in word list", "min": 1, "max": 10, "step": 1},
        "y": {"label": "Recall likelihood", "min": 0, "max": 1, "step": null},
        "y2": null,
        "qualitative": true,
        "series": [
          {
            "label": "Immediate recall",
            "points": [[1, 0.85], [2, 0.7], [3, 0.5], [4, 0.35], [5, 0.3], [6, 0.3], [7, 0.4], [8, 0.55], [9, 0.75], [10, 0.9]],
            "style": "line",
            "axis": "left"
          },
          {
            "label": "30 s filled delay",
            "points": [[1, 0.85], [2, 0.7], [3, 0.5], [4, 0.35], [5, 0.3], [6, 0.3], [7, 0.3], [8, 0.3], [9, 0.3], [10, 0.3]],
            "style": "line",
            "axis": "left"
          }
        ],
        "segments": null,
        "annotations": null,
        "intervals": null
      }
    },
    {
      "template": "question-set",
      "heading": "Explain the evidence",
      "questions": [
        "Immediate recall favours early and final words. Explain the model’s account of each advantage.",
        "After 30 seconds of counting, the final-word advantage falls but the early-word advantage remains. Explain why.",
        "Why does this pattern support separate STM and LTM stores rather than prove the whole model?"
      ],
      "instruction": "Link each finding to a store or process.",
      "picture": null
    },
    {
      "template": "visual-text",
      "heading": "KF: is STM one store?",
      "lead": "Shallice and Warrington (1970) studied KF after brain injury.",
      "points": [
        "KF’s verbal STM was severely impaired, especially for heard material.",
        "His visual STM was relatively better preserved.",
        "This challenges one unitary STM store: its components can be affected differently."
      ],
      "figure": {
        "kind": "flow",
        "shows": "The contrast between KF’s verbal and visual short-term memory",
        "alt": "KF’s short-term memory performance differed: verbal memory was severely impaired, while visual memory was relatively better preserved.",
        "title": null,
        "nodes": ["KF: STM performance", "Verbal: impaired", "Visual: better preserved"],
        "links": [
          {"from": 0, "to": 1, "label": null},
          {"from": 0, "to": 2, "label": null}
        ]
      }
    },
    {
      "template": "practice",
      "heading": "Evaluate the model",
      "questions": [
        "A counting delay reduced recall of final words but spared early words. Write a supporting argument using this finding.",
        "KF had poor verbal STM but relatively preserved visual STM. Write a challenge to the model using this finding.",
        "Stretch: explain why KF challenges a single STM store without showing that separate STM and LTM stores do not exist."
      ],
      "instruction": "Use: claim → evidence → explanation.",
      "picture": null
    },
    {
      "template": "practice",
      "heading": "Apply the model: a station announcement",
      "questions": [
        "Leila hears a platform number but attends to a message instead. Explain why she may not remember the announcement.",
        "She hears it again and repeats it until boarding. Explain the process and the store’s likely coding and duration without rehearsal.",
        "Months later, she recalls the station’s name from a previous trip. Explain the transfer and describe that store’s coding, capacity and duration."
      ],
      "instruction": "Explain each situation using the model.",
      "picture": null
    }
  ]
}
